  "secrets.wall": "GEBROCHENES RELAIS\nZiel und Feuer auf den glühenden Riss.",
  "secrets.plates": "GEHEIMHALTUNG · DRUCKPLATTEN\nSchritt 1 → 2 → 3: links, rechts, in der Mitte.",
  "secrets.runes": "GEHEIMHALTUNG · BEATRUNEN\nSchießen Sie links, rechts, mitten auf ein Glockenspiel.\nGoldwürfel markieren den Beat, auch wenn sie gedämpft sind.",
  "secrets.braziers": "GEHEIMHALTUNG · DREI BRASSEN\nFeuerwaffen zünden die braziers an.\nKein Feuer? Stehen Sie auf dem Goldpolster, dann zielen und feuern.",
  "secrets.ice": "GEHEIMHALTUNG · KREUZUNGEN, GEFROREN\nFrieren Sie den blauen Kristall ein und durchqueren Sie dann das Wasser.\nKein Frost? Ladung auf dem Goldkissen, dann schießen.",
  "secrets.done": "RELAIS WIEDERHERGESTELLT · RELIQUIE VERLIEHEN\nBesuchen Sie das grüne Terminal. Der Roboter kennt einen Tanz.",
