  "secrets.shadow_intro": "ICH KENNE JEDE DEINER BEWEGUNGEN.",
  "secrets.golden_name": "Goldener König",
  "secrets.shadow_name": "Shadow Hero",
  "secrets.golden_title": "GEHEIMHALTUNG · DER SAMMLER DER SAMMLER",
  "secrets.shadow_title": "GEHEIMHALTUNG · DEINE REFLEXION ERINNERT SICH",
  "secrets.skin": "Pixel-Relay-Rüstung",
  "secrets.skin_short": "Pixel-Relay",
  "secrets.skin_condition": "Lösen Sie einen geheimen Raum oder entdecken Sie den alten Richtungscode.",
  "secrets.category": "GEHEIMHALTUNG",
  "secrets.lore_name": "Das vergessene Relais",
  "secrets.developer_name": "Die Nachtschicht",
  "secrets.lore": "Die Wartungsmannschaft versteckte eine Werkstatt hinter einer falschen Wand. Drei Lampen erinnern sich an die Reihenfolge: links, rechts, in der Mitte. Jedes gelöste Relais sendet immer noch ein Dankeschön.",
  "secrets.developer_lore": "Ein winziger Raum für alle, die die Inseln am Laufen gehalten haben. Der Roboter tanzt, weil endlich jemand zurückkam. Danke fürs Spielen.",
  "secrets.king_lore": "GEHEIMNIS: Drei fehlende Goldwanzen weckten ihren König. Seine Krone erinnert sich an jede gestohlene Münze. Beobachten Sie die goldenen Landungsringe. Bewegen Sie sich weiter und beobachten Sie, wie es aufgeht.",
  "secrets.shadow_lore": "GEHEIMNIS: Eine makellose Nacht hinterlässt eine Reflexion. Sie durchläuft deine Waffenmuster; ihre geliehene Macht hat sichere Grenzen. Bewege dich weiter und beobachte, wie sie aufgeht.",
  "secrets.a_room": "Abseits der Karte",
  "secrets.a_room_desc": "Löse einen geheimen Relaisraum.",
  "secrets.a_king": "Royal Audit",
  "secrets.a_king_desc": "SECRET: Fange drei Goldbugs in einem Lauf, wecke die goldene Statue und besiege den Goldenen König.",
  "secrets.a_shadow": "Besser als mein Schatten",
  "secrets.a_shadow_desc": "SECRET: Besiegen Sie Ihr Spiegelbild nach einer makellosen Nachtbühne.",
  "secrets.a_code": "Alte Schule",
  "secrets.a_code_desc": "Entdecken Sie den alten Richtcode auf dem Titelbildschirm.",
