  "content.84fee1b908": "Seitenwindschaufeln",
  "content.21f48f0714": "Gepaarte Sichelblätter kreuzen sich nach außen und schneiden dann entlang eines gekrümmten Rückwegs zurück.",
  "content.bceb0fd05d": "Teslaspulen",
  "content.20e9db560e": "Sie zappen Feinde in der Nähe und elektrifizieren die Leitung zur vorherigen Spule.",
  "content.3fa4624af4": "Raketenschwarm",
  "content.d5a30861d8": "Fans winzige Zielflugkörper in einer gestaffelten Welle. Kleine Explosionen sättigen die Menge.",
  "content.33308c454a": "Prismensplitter",
  "content.7b8ce4b3a3": "Kristalle prallen zwischen Feinden ab. Jeder spaltet sich beim ersten Treffer in zwei kleinere Kristalle.",
  "content.6ae4da1570": "Strahlenpeitsche",
  "content.dda58a2099": "LINKER KLICK: fegen Sie einen flexiblen Balken über einen weiten Bogen. Jede Schaukel trifft einen Feind einmal.",
  "content.d20d4a8f64": "Taschenwächter",
  "content.5191e9018c": "RIGHT CLICK: Setzen Sie einen Wachposten auf den Cursor. Er verfolgt und erschießt Gegner; Platzieren eines anderen ersetzt das älteste.",
  "content.b2ecb120df": "Glas Gale",
  "content.1519201745": "FUSION von Crosswind Blades + Prism Shards. Halbmondblätter platzen in Kristallblitze, während Splitter durch die Menge prallen.",
  "content.1ded80863d": "Hornhautgitter",
  "content.5085777882": "FUSION von Tesla Coils + Swarm Missiles. Eine elektrische Raketenbatterie: Mikro-Raketensprengungen springen Blitze durch nahegelegene Feinde, während Spulen deine Spur bewachen.",
  "content.7bd71968dd": "Ripostenzelle",
  "content.f9fa5592c1": "Slipstream",
  "content.b3b5901935": "Encore",
  "content.55bf66186a": "Kassenkondensator",
  "content.718a53f70a": "Zweite Hand",
  "content.45ac1a13ab": "Auswerfsitz",
  "content.b9fe1a7ba3": "Jack in der Box",
  "content.907ba6a6a3": "Herd",
  "content.f83f00dc6d": "Wandblumen",
  "content.d8eb186561": "Kalte Front",
