  "content.dd10e5feed": "Standing Ovation",
  "content.1b913d3b3f": "Wischen Sie einen flexiblen Balken über einen weiten Bogen. Jede Schaukel trifft einen Feind einmal.",
  "content.a0fe8c20b1": "Setzen Sie einen Wachposten am Cursor ein. Er verfolgt und erschießt Feinde; Ein anderer ersetzt den ältesten.",
  "content.672418ed7d": "Parry: Treffer gewinnen +⟪0⟫ Schaden für ⟪1⟫s vor Multiplikatoren setzen.",
  "content.9ec4a01350": "Perfekter Dash: Orbit- und Trail-Hits verursachen +⟪0⟫% Schaden für ⟪1⟫.",
  "content.f6d86f700c": "Verwenden Sie Ihre ultimative: +⟪0⟫% Schaden für ⟪1⟫s.",
  "content.3347d5257c": "Cash in einer Combo: Treffer gewinnen +⟪0⟫ Schaden für ⟪1⟫s. Kein Goldbonus.",
  "content.73023179eb": "Nach einem Rewind endet: +⟪0⟫% Schaden für ⟪1⟫s.",
  "content.9f02fc66b3": "Überlebe den Mecha-Ausstieg: +⟪0⟫% Schaden für ⟪1⟫s, einschließlich der Ausstiegsexplosion.",
  "content.c21d055973": "Öffnen Sie eine Truhe: Eine ⟪0⟫m Shock Nova verursacht ⟪1⟫ Schaden.",
  "content.4796d804bf": "Im Feuer deiner Flammenstiefel verursachen Feuer- und Spurtreffer +⟪0⟫% Schaden.",
  "content.1c57742cae": "Innerhalb von ⟪0⟫ m Deckung: Orbit und Area treffen +⟪1⟫% Schaden.",
  "content.b1bbcf2021": "Ab ⟪0⟫m Entfernung verursachen Frost- und Kettentreffer +⟪1⟫% Schaden.",
  "content.a58a60981e": "Jeder Treffer +⟪0⟫ Schaden. Max Leben x⟪1⟫. Vor Multiplikatoren setzen.",
  "content.5e37395e25": "Jeder Treffer verliert ⟪0⟫ Schaden, dann x⟪1⟫. Starke Treffer gewinnen; Ordnung zählt.",
  "content.352a455638": "Dein Brand gibt Verbündeten +⟪0⟫% kritische Trefferchance gegen diesen Gegner (Teamlimit +⟪1⟫%).",
  "content.0836247367": "Andere Verbündete innerhalb von ⟪0⟫m laden alle Waffen ⟪1⟫% schneller nach (Team-Cap + ⟪2⟫% Geschwindigkeit).",
  "content.e76459c2b5": "Pariert ein Verbündeter innerhalb von ⟪0⟫m, erzeugst du eine Schocknova mit ⟪1⟫m Radius und ⟪2⟫ Schaden. Abklingzeit: ⟪3⟫s.",
  "content.87006ad396": "Teile ⟪0⟫% der tatsächlich durch Kills geheilten Lebenspunkte mit jedem Verbündeten innerhalb von ⟪1⟫m (max. ⟪2⟫%).",
  "content.5cb95a9e84": "Weicht ein Verbündeter innerhalb von ⟪0⟫m perfekt aus, wirst du ⟪1⟫s unverwundbar (max. ⟪2⟫s). Abklingzeit: ⟪3⟫s.",
  "content.07d6955765": "Ein Verbündeter verwendet einen ultimativen innerhalb von ⟪0⟫m: Ihre Treffer verursachen +⟪1⟫% Schaden für ⟪2⟫s.",
  "content.7042a34e52": "Gale Reapers",
  "content.4147d8d8ce": "Sechs riesige Halbmonde schlugen bei ihrer Rückkehr erneut zu.",
  "content.17445c9856": "MAX SEITENWINDSCHAUFELN + STRAHLSTRAHLTRIEBWERKE",
  "content.e8a4b67f4f": "Thunder Grid",
  "content.3c22ee344d": "Sechs Langstreckenspulen weben einen schnell pulsierenden Blitzzaun.",
  "content.7c2b3d0cd9": "MAX TESLA SPULEN + AKKUPACK",
  "content.0551ec041f": "Hornet Armada",
  "content.ef5520301e": "Vierzehn schnelle Zielsuchhornissen brechen in einer rollenden Welle hervor.",
  "content.7254961088": "MAX-SCHWARMRAKETEN + POWER CELL",
  "content.c00761a1fb": "Kaleidoskop",
  "content.713510f70b": "Vier Kristalle prallen sechsmal ab und teilen sich in kleinere Scherben.",
  "content.3f02a91752": "MAX PRISMENSCHERBEN + KRYORUNDEN",
  "content.7eec71fe00": "Sonnencreme",
  "content.173f69c5f1": "Eine breite brennende Peitsche (Feuer), +40 Grad und 25% Schaden.",
  "content.74236350d1": "ENTWICKLUNG DER STRAHLPEITSCHE",
  "content.bee03eb48f": "Zwergpilz",
  "content.c3d026a983": "Eine zweite Peitsche fegt hinter dir her. Beide Schockfeinde.",
  "content.8847d2f7b5": "Gletscher Sentry",
  "content.c1de1b50b7": "Wide Frost Schrauben durchdringen 2 Feinde. +20% Schaden.",
  "content.c2234f7ae0": "ENTWICKLUNG DER TASCHENWACHE",
