  "text.burn_shock_and_freeze_two_on_one_enemy_make_a_co_4f8f92": "Brennen, Schock und Einfrieren. Zwei Gegner machen eine Combo: Burn + Shock = OVERLOAD, kill a frozen enemy = SHATTER, blast a burning one = NAPALM.",
