  "text.bought_in_the_shop_after_each_boss_damage_flows__59dc04": "Gekauft im Laden nach jedem Chef. Schaden fließt durch ihre 5 Slots von links nach rechts, also ist ihre Bestellung wichtig.",
  "text.style_264709": "STIL",
  "text.fast_kills_perfect_dodges_and_parries_raise_your_93f271": "Schnelle Kills, perfekte Ausweichmanöver und Parries erhöhen Ihren Stil (D bis SS) für mehr Punktzahl und XP.",
