  "text.click_a_key_slot_then_press_the_new_key_esc_canc_7f55da": "Klicken Sie auf einen Tastenschlitz und drücken Sie dann die neue Taste (Esc bricht ab). Maus: linkes Feuer, rechte Ladung, mittlere Bombe. Gamepad-Layout ist behoben:",
  "text.reset_defaults_cb53b2": "STANDARD WIEDERHERSTELLEN",
  "text.co_op_for_up_to_4_players_one_player_hosts_and_s_f0eb31": "Koop für bis zu 4 Spieler. Ein Spieler hostet und teilt einen Code; Freunde schließen sich ihm an.",
  "text.your_name_7801bf": "DEIN NAME",
  "text.host_game_ee1e1b": "SPIEL HOSTEN",
