  "text.start_game_d7700f": "SPIEL STARTEN",
  "text.pick_your_left_click_right_click_and_special_you_2606ce": "Wähle deine Primärwaffe, Sekundärwaffe und Spezialfähigkeit. Du behältst sie den ganzen Run und verbesserst sie beim Levelaufstieg.",
  "text.pick_a_relic_754306": "RELIKT WÄHLEN",
  "text.the_secret_merchant_gives_you_one_for_free_relic_1cdf8d": "Der geheime Händler schenkt dir eine. Reliquien wirken dauerhaft und belegen keinen Mod-Platz.",
  "text.waiting_1869d5": "WARTEN",
  "text.your_teammates_are_still_choosing_c955ce": "Dein Team wählt noch:",
  "text.shop_7e0e61": "LADEN",
  "text.achievements_carry_over_between_runs_some_add_ne_1611a2": "Erfolge übertragen sich zwischen den Läufen. Einige fügen neue Waffen zu Ihren Level-up-Karten hinzu.",
  "text.save_data_ac3268": "SPEICHERDATEN",
  "text.your_progress_saves_by_itself_to_back_it_up_or_m_dbc518": "Ihr Fortschritt speichert sich selbst. Um es zu sichern oder auf einen anderen PC zu verschieben, speichern Sie es in einer Datei und laden Sie diese Datei dann auf den anderen PC.",
  "text.save_to_file_12f46f": "IN DATEI SPEICHERN",
  "text.load_from_file_56e00a": "AUS DATEI LADEN",
