  "text.weekly_co_op_this_week_s_seed_and_rules_for_ever_633f78": "Wöchentliche Koop: Samen und Regeln dieser Woche für jedes Team, jeweils ein Rookie-Kit und ein Teamboard.",
  "text.versus_swarm_one_player_is_the_overlord_and_send_44cae9": "Versus Swarm: Ein Spieler ist der Overlord und schickt die Wellen von oben; der Rest überlebt den Timer und schlägt den Boss.",
