  "text.king_bopper_ex_ac050c": "King Bopper EX",
  "text.the_bounce_strikes_back_4fe069": "DER BOUNCE SCHLÄGT ZURÜCK",
  "text.royal_quake_every_landing_sends_a_ring_23eb82": "KÖNIGLICHES BEBEN: JEDE LANDUNG SCHICKT EINEN RING",
  "text.ex_fury_b862b0": "EX-WUT",
  "text.rampage_rex_inferno_7ff304": "Rampage Rex: Inferno",
  "text.everything_burns_cc2a67": "ALLES BRENNT",
  "text.inferno_fire_breath_already_a4afaa": "INFERNO: FEUER ATMEN BEREITS",
  "text.meltdown_6f4c45": "MELTDOWN",
  "text.hive_queen_nightshade_64566b": "Hive Queen: Nightshade",
  "text.the_swarm_remembers_da1bcf": "DER SCHWARM ERINNERT SICH",
  "text.nightshade_walls_and_hives_together_23fb15": "NIGHTSHADE: WÄNDE UND BIENENSTÖCKE ZUSAMMEN",
  "text.the_last_brood_d6aa69": "DIE LETZTE BRUT",
  "text.titan_goliath_5e28c8": "Titan Goliath",
  "text.the_mountain_that_woke_up_83ba91": "DER BERG, DER AUFWACHTE",
  "text.titan_armour_plate_8de89e": "Titanpanzerplatte",
  "text.titan_hand_core_7b1c24": "Titan Hand Core",
  "text.titan_eye_08de1f": "Titan Auge",
  "text.once_tiny_garden_helpers_these_machines_now_mist_1558e4": "Einst winzige Gartenhelfer, verwechseln diese Maschinen jetzt jeden Stiefel mit einem Unkraut.",
  "text.the_islands_oldest_delivery_bot_still_insists_th_70852e": "Der älteste Lieferbot der Inseln besteht immer noch darauf, dass jedes Paket persönlich ankommt.",
  "text.a_courier_with_no_address_left_to_deliver_to_its_14143a": "Ein Kurier ohne Adresse, an den Sie liefern können. Seine Route endet, wo auch immer Sie stehen.",
  "text.a_retired_fireworks_launcher_still_rehearsing_fo_c984e2": "Ein pensioniertes Feuerwerk, das immer noch für ein Festival probet, das nie kam.",
  "text.its_compass_broke_years_ago_it_has_been_checking_adba8f": "Sein Kompass ist vor Jahren kaputt gegangen. Seitdem überprüft er alle Richtungen.",
  "text.three_short_knocks_were_once_the_repair_crew_s_s_bcacff": "Drei kurze Schläge waren einst die geheime Begrüßung der Reparaturmannschaft. Dieser Bot erinnert sich.",
  "text.the_watchtower_sentry_can_count_the_scratches_on_c73dcc": "Die Wachtturmwache kann die Kratzer auf Ihrem Helm von der anderen Seite der Insel zählen.",
  "text.a_quarry_hauler_with_excellent_acceleration_and__1029b6": "Ein Steinbruchschlepper mit ausgezeichneter Beschleunigung und absolut keine Bremsen.",
  "text.under_that_heavy_shell_is_a_remarkably_small_bat_5d4742": "Unter dieser schweren Schale befindet sich eine bemerkenswert kleine Batterie und ein enormes Pflichtgefühl.",
  "text.the_warning_sticker_fell_off_the_warning_noise_f_02ac0e": "Der Warnaufkleber fiel ab. Das Warngeräusch funktioniert glücklicherweise immer noch.",
  "text.the_recycling_plant_called_this_self_repair_the__92b56d": "Die Recyclinganlage nannte dies Selbstreparatur. Die Außendienstmitarbeiter nennen es zusätzlichen Papierkram.",
  "text.a_little_piece_of_a_much_bigger_problem_determin_9984a9": "Ein kleines Stück eines viel größeren Problems, entschlossen, seinen eigenen Weg zu gehen.",
  "text.the_factory_foreman_never_received_the_shutdown__614054": "Der Fabrikvorarbeiter erhielt nie den Abschaltungsbefehl. Die Produktion geht weiter.",
  "text.built_to_shelter_workers_from_falling_rock_it_st_30a8cc": "Gebaut, um Arbeiter vor fallenden Felsen zu schützen; es stellt immer noch alle anderen an die erste Stelle.",
  "text.its_medical_license_expired_with_the_old_network_4e514c": "Seine medizinische Lizenz lief mit dem alten Netzwerk aus. Seine Art am Bett bleibt begeistert.",
  "text.the_island_drains_needed_a_maintenance_robot_tha_25ca9a": "Die Inselabflüsse brauchten einen Wartungsroboter, der springen konnte. Niemand spezifizierte einen Landeplatz.",
  "text.an_irrigation_system_that_found_the_wrong_kind_o_7b0a51": "Ein Bewässerungssystem, das die falsche Art von Kanister im Versorgungsschuppen fand.",
  "text.every_loose_bolt_on_the_islands_eventually_ends__83950b": "Jeder lose Bolzen auf den Inseln endet schließlich in den Taschen dieses Sammlers.",
  "text.the_first_bopper_promoted_itself_when_the_human__947489": "Der erste Bopper warb selbst, als die menschlichen Aufseher gingen. Seine Krone ist eine Antenne.",
  "text.the_excavation_project_stopped_at_bedrock_rex_to_8bf630": "Das Ausgrabungsprojekt endete am Grundgestein. Rex nahm das persönlich.",
  "text.from_her_aerial_command_post_she_conducts_the_fa_f2d7d4": "Von ihrem Luftkommandoposten aus dirigiert sie den Fabrikschwarm wie eine Blaskapelle.",
  "text.the_central_relay_has_waited_through_a_thousand__3619a8": "Das zentrale Relais hat durch tausend ruhige Sonnenuntergänge gewartet. Jetzt ruft jede Insel sofort an.",
  "text.a_junior_supervisor_practising_a_royal_entrance__43e53e": "Ein Junior Supervisor übt einen königlichen Eingang vor der eigentlichen Promotion.",
  "text.a_prototype_digger_that_already_dreams_of_moving_bf3a30": "Ein Prototyp Bagger, der bereits davon träumt, Berge zu bewegen.",
  "text.her_first_command_assignment_is_this_island_she__03b2ed": "Ihr erster Befehlsauftrag ist diese Insel. Sie will einen guten Eindruck machen.",
  "text.a_portable_workshop_unfortunately_its_only_repai_004521": "Eine tragbare Werkstatt. Leider besteht ihr einziger Reparaturplan darin, mehr Ärger zu machen.",
  "text.the_network_sends_this_collector_when_an_overdue_f55499": "Das Netzwerk schickt diesen Sammler, wenn ein überfälliger Arbeitsauftrag zur Legende wird.",
  "text.the_newest_member_of_the_recovery_crew_brought_a_cc8b08": "Das neueste Mitglied der Bergungsmannschaft brachte einen geliehenen Helm und eine Karte mit Buntstift mit, die sich beide als erstaunlich zuverlässig erwiesen haben.",
  "text.a_rescue_worker_who_once_held_a_collapsing_bridg_44755c": "Ein Rettungshelfer, der einst eine einstürzende Brücke zusammenhielt, bis der letzte Kurier überquerte. Die schwere Rüstung dient vor allem dem Seelenfrieden aller anderen.",
  "text.the_old_island_racing_champion_traded_prize_mone_a07a46": "Der alte Inselrennmeister tauschte Preisgelder gegen ein Paar Versuchsstiefel ein. Die Brandmarken sind jetzt eine eingetragene Unterschrift.",
  "text.a_radio_operator_who_can_hear_the_rhythm_hiding__b613cb": "Ein Funker, der den sich im Maschinengeplapper versteckenden Rhythmus hören kann. Jeder Schuss wird auf den nächsten Takt getaktet.",
  "text.enemy_92b09d": "FEIND",
  "text.a_veteran_of_the_old_island_network_patched_up_a_9525a3": "Ein Veteran des alten Inselnetzes, geflickt und auf Patrouille zurückgeschickt.",
  "text.keep_moving_and_watch_its_wind_up_e55101": "Halten Sie sich in Bewegung und beobachten Sie seine wind-up.",
  "text.biome_05c008": "BIOM",
  "text.the_repair_crews_left_flowers_growing_between_th_c2ad6c": "Die Reparaturteams ließen Blumen zwischen den Leiterplatten wachsen. Jedes Abenteuer beginnt irgendwo hell.",
  "text.buried_relay_towers_still_hum_beneath_the_sunset_9473fb": "Vergrabene Relaistürme summen immer noch unter dem Sonnenuntergangssand. Der Wind erinnert sich an ihr Lied.",
  "text.the_mountain_antennae_catch_signals_from_stars_n_ca0ea0": "Die Bergantennen fangen Signale von Sternen auf, die niemand genannt hat. Eis bewahrt die alten Maschinen.",
  "text.deep_under_the_islands_the_planet_keeps_its_own__c22366": "Tief unter den Inseln hält der Planet seinen eigenen Ofen am Laufen. Die Maschinen hier haben gelernt, die Hitze zu lieben.",
  "text.another_island_on_the_old_relay_route_waiting_to_cc8d43": "Eine weitere Insel auf der alten Relaisroute, die darauf wartet, wiederentdeckt zu werden.",
  "text.relay_gold_armour_308d74": "Relais Gold Armour",
