  "text.veteran_55a899": "Veteran",
  "text.storm_drones_54e73f": "Sturmdrohnen",
  "text.crackling_drones_chain_lightning_off_every_enemy_6754b6": "Knackende Drohnen ketten Blitze von jedem Feind, den sie bonken, und die Sturmbolzen springen 2 weitere Male.",
  "text.napalm_rockets_8fdd8d": "Napalm-Raketen",
  "text.rockets_set_everything_ablaze_and_splash_burning_5976d9": "Raketen setzen alles in Brand und spritzen brennende Napalmbecken, wo sie landen. Ihre Spur brennt immer noch.",
  "text.ice_saws_8e4ea7": "Eissägen",
  "text.frozen_saw_blades_freeze_what_they_slice_shatter_1eb42a": "Gefrorene Sägeblätter gefrieren, was sie schneiden; zerschmetternde Novas pulsieren immer noch um dich herum.",
  "text.supernova_field_f4b2cc": "Supernova-Feld",
  "text.a_blazing_storm_field_its_novas_freeze_shock_and_0c32c6": "Ein loderndes Sturmfeld. Seine Novas frieren ein, schockieren und blasen gefrorene Feinde in kleinen Explosionen auseinander.",
  "text.tesla_traps_c80060": "Tesla-Falle",
  "text.mines_that_burst_into_chain_lightning_jumping_th_963fb4": "Minen, die in Kettenblitze ausbrachen und um jede Explosion herum durch die Menge sprangen.",
  "text.prism_satellites_532c41": "Prismensatelliten",
  "text.rainbow_satellites_orbit_you_flashing_light_burs_ca2017": "Regenbogensatelliten umkreisen Sie, blinkendes Licht platzt beim Treffer, während vier Prismenstrahlen einen vollen Kreis drehen.",
  "text.dragon_cannon_7ad214": "Drachenkanone",
  "text.a_turret_that_breathes_18_piercing_fireballs_at__290063": "Ein Turm, der 18 durchdringende Feuerbälle auf die Menge atmet, und eine lodernde Spur hinter dir.",
  "text.comet_swarm_766fee": "Kometenschwarm",
  "text.bouncing_comets_explode_on_every_ricochet_and_6__d30f4a": "Springende Kometen explodieren auf jedem Abpraller, und 6 Sterne regnen auf die Menge.",
  "text.meteor_barrage_db8aa0": "Meteor-Barriere",
  "text.burning_meteor_rockets_with_bigger_blasts_that_s_7fc540": "Brennende Meteorraketen mit größeren Explosionen, die die Menge in Brand setzen, plus einen schwereren Sternfall.",
  "text.volt_ricochet_c8ce40": "Volt Ricochet",
  "text.electric_drones_bounce_2_more_times_and_arc_ligh_8347e5": "Elektrische Drohnen hüpfen 2 weitere Male und blitzschnell von jedem Feind, den sie getroffen haben.",
  "text.fusion_of_17fb35": "FUSION ⟪0⟫ + ⟪1⟫. ⟪2⟫",
