  "text.bulwark_671b9a": "Bollwerk",
  "text.40_life_1_armor_10_slower_starts_with_a_zap_fiel_7923b3": "+40 Leben, +1 Rüstung, 10% langsamer. Beginnt mit einem Spaltfeld. ULTIMATE: Titan Stomp.",
  "text.15_faster_dash_recharges_25_sooner_20_life_start_b2afa6": "15% schneller, Dash lädt 25% früher auf, -20 Leben. Beginnt mit Blaze Boots. ULTIMATE: Sonic Blitz.",
  "text.ace_37b120": "Ass",
  "text.20_damage_10_crit_chance_slower_right_click_star_0f8854": "+20% Schaden, +10% kritische Trefferchance, langsamerer Rechtsklick. Startet mit Kettenblitz. ULTIMATIVE FÄHIGKEIT: Zielsturm.",
  "text.duelist_be1929": "Duellant",
  "text.no_dash_the_dash_key_parries_a_longer_parry_wind_338748": "Ein längeres Parry-Fenster, und jede Parry in einer Kette fügt +12% Schaden (bis zu x6) hinzu, während es dauert. +5% Krit Chance. ULTIMATE: Blade Dance.",
  "text.furnace_7399ee": "Hochofen",
  "text.heats_up_while_standing_still_up_to_60_damage_an_4ebd30": "Erhitzt sich im Stillstand: bis zu +60% Schaden und eine brennende Aura, die wächst. Bewegen entlüftet die Hitze. +30 Leben, 15% langsamer. ULTIMATE: Meltdown.",
  "text.twin_f207e9": "Zwilling",
  "text.a_small_mirror_twin_walks_beside_you_and_copies__0b3455": "Ein kleiner Spiegelzwilling geht neben dir und kopiert deinen linken Klick bei halbem Schaden. -10 Leben. ULTIMATE: Mirror Storm.",
