  "text.standard_eb6d8a": "Standard",
  "text.survive_each_stage_beat_the_boss_take_the_portal_c31e5f": "Überleben Sie jede Stufe, schlagen Sie den Boss, nehmen Sie das Portal. Endlose Stufen.",
  "text.endless_263047": "Endlos",
