  "text.bullet_carnival_8737a1": "Bullenkarneval",
  "text.enemy_shots_travel_twice_as_fast_8e413e": "Feindliche Schüsse reisen doppelt so schnell.",
  "text.level_up_5b0ee6": "LEVELAUFSTIEG!",
  "text.pick_1_of_3_cards_click_or_keys_1_3_the_ribbon_a_c71357": "Wählen Sie 1 von 3 Karten (Klick oder Tasten 1-3). Das Band unten sagt, was es aufwertet: LEFT CLICK, RIGHT CLICK, SPECIAL, AUTO WEAPON oder ITEM.",
  "text.evolution_fork_634218": "ENTWICKLUNG WÄHLEN",
  "text.enough_ranks_to_evolve_pick_one_of_the_two_forms_2fd106": "Genug Ränge, um sich zu entwickeln! Wählen Sie EINS der beiden Formulare. Jedes ändert die Funktionsweise des Elements und fügt einen Tag hinzu, den das neue Mods abtasten kann.",
  "text.the_shop_37cbe7": "DER LADEN",
  "text.mods_sit_in_5_slots_and_change_how_your_damage_w_71e69c": "Mods sitzen in 5 Slots und ändern, wie Ihr Schaden funktioniert. Gold, das Sie halten, verdient Zinsen in jeder Phase klar, so dass sich das Sparen auszahlen kann.",
  "text.mod_order_matters_7598df": "DIE MOD-REIHENFOLGE ZÄHLT",
  "text.damage_flows_through_your_mods_left_to_right_dam_1e221f": "Schaden fließt durch deinen Mods LINKEN nach RECHTS: (Schaden + fügt hinzu) x mults. Bewege dich flach \"+Schaden\" Mods vor \"x Schaden\" mit den Pfeilen. Echo kopiert den Mod nach rechts.",
  "text.elite_07576c": "ELITE!",
  "text.a_big_tough_enemy_with_a_modifier_shield_fast_sp_891aa6": "Ein großer, zäher Feind mit einem Modifikator (Schild, schnell, spaltend...). Seine Schädelstange zeigt sein Leben. Schlagen Sie es für eine Schatztruhe.",
  "text.exposed_e6c328": "VERWUNDBAR",
  "text.right_click_hits_expose_enemies_30_damage_from_e_38bc87": "Rechtsklick trifft Gegner aussetzen: +30% Schaden von allen für 4 s. Öffnen Sie mit dem rechten Klick, beenden Sie mit der linken Seite.",
  "text.burn_ticks_damage_shock_makes_enemies_take_20_fr_22dfd5": "Verbrennen Sie Zecken Schaden, Shock macht Feinde nehmen +20%, Freeze stoppt sie.",
  "text.status_combo_f68922": "STATUS COMBO!",
  "text.burn_shock_overload_blast_kill_a_frozen_enemy_sh_c6ed94": "Eine Explosion auf einem brennenden Feind = NAPALM. Mods kann jeden stärker machen.",
  "text.it_changes_its_attacks_at_66_and_33_life_red_zon_bf37e5": "Bei 66% und 33% Leben ändern sich seine Angriffe. Rote Flächen und Linien warnen dich: Sprinte hindurch (⟪0⟫) oder pariere Schüsse (⟪1⟫).",
  "text.treasure_chest_81663c": "SCHATZTRUHE",
  "text.walk_into_it_for_a_free_item_on_the_spot_the_arr_3230d7": "Gehen Sie in sie für einen freien Gegenstand an der Stelle. Der Pfeil am Bildschirmrand zeigt auf den nächsten.",
  "text.special_ready_f6a478": "SPEZIALFERTIG",
  "text.press_or_middle_click_for_your_special_it_rechar_03aa5b": "Drücken Sie ⟪0⟫ (oder Mittelklick) für Ihr Special. Es lädt sich im Laufe der Zeit auf.",
  "text.ultimate_ready_d08f2b": "ENDGÜLTIG BEREIT",
  "text.press_perfect_dodges_parries_and_kills_charge_yo_916d6b": "Drücken Sie ⟪0⟫! Perfekte Ausweichmanöver, Parries und Kills laden das ultimative Ihres Helden auf.",
  "text.style_meter_8e60e9": "STILMESSER",
  "text.fast_kills_perfect_dodges_and_parries_raise_your_9b344a": "Schnelle Kills, perfekte Ausweichmanöver und Parries erhöhen Ihren Stil von D auf SS. Höherer Stil gibt mehr Punktzahl und XP.",
  "text.gear_f7f969": "ZAHNRAD",
  "text.each_gear_rerolls_one_set_of_level_up_cards_on_t_5e783d": "Jedes Zahnrad rollt einen Satz von Level-up-Karten (⟪0⟫ auf dem Level-up-Bildschirm).",
  "text.stage_clear_4e29fa": "ABSCHNITT GESCHAFFT",
  "text.walk_into_the_portal_for_the_next_stage_every_st_adf1cd": "Geh durch das Portal zum nächsten Abschnitt. Jeder Abschnitt wird schwerer; jeder 4. endet mit dem Endboss.",
  "text.a_teammate_revives_you_by_standing_next_to_you_f_b91da8": "Ein Teamkollege belebt Sie, indem er 3 s neben Ihnen steht. Klicken Sie, um einen anderen Teamkollegen zu sehen.",
  "text.teammate_down_47afc6": "TEAMMITGLIED AM BODEN",
  "text.stand_next_to_them_for_3_s_to_revive_them_you_bo_80d4d7": "Stehen Sie für 3 s neben ihnen, um sie wiederzubeleben.",
  "text.walk_around_with_or_the_left_stick_you_always_fa_4087eb": "Gehen Sie mit ⟪0⟫ ⟪1⟫ ⟪2⟫ ⟪3⟫ oder dem linken Stock herum.",
  "text.aim_and_fire_e2180c": "ZIEL UND FEUER",
  "text.aim_with_the_mouse_or_right_stick_and_hold_left__395851": "Ziele mit Maus oder rechtem Stick und halte LINKSKLICK, um mit ⟪0⟫ zu schießen. Zerstöre die ⟪1⟫ Zielbots.",
  "text.hold_right_click_or_x_for_your_its_hits_expose_e_c35ec0": "Halten Sie RIGHT CLICK (oder X) für Ihre ⟪0⟫. Seine Treffer EXPOSE Feinde: +30% Schaden von allen für 4 s. Expose den großen Bot.",
  "text.press_to_dash_you_can_t_be_hit_mid_dash_dash_thr_ff9c38": "Drücken Sie ⟪0⟫ zum Dash: Sie können nicht mitten im Dash getroffen werden. Dash durch einen rosa Schuss, kurz bevor er Sie trifft.",
  "text.press_or_b_right_as_a_pink_shot_reaches_you_to_p_99aaf3": "Drücken Sie ⟪0⟫ (oder B) rechts, wenn ein rosa Schuss Sie erreicht, um ihn am Shooter zurück zu PARRY.",
  "text.your_special_is_ready_press_or_rb_to_set_off_you_fa2e3b": "Ihr Special ist fertig: Drücken Sie ⟪0⟫ (oder RB), um Ihre ⟪1⟫ neben den Bots zu starten.",
  "text.ultimate_df1d2d": "ULTIMATIVE FÄHIGKEIT",
  "text.perfect_dodges_parries_and_kills_charge_your_her_5caa68": "Perfekte Ausweichmanöver, Parries und Kills laden das ULTIMATE Ihres Helden auf. Es ist voll: drücken Sie ⟪0⟫ (oder R3).",
  "text.level_up_529820": "LEVEL UP",
  "text.kills_drop_xp_gems_that_fly_to_you_a_full_xp_bar_8d848d": "Eine volle XP-Leiste ist ein Level-up: Wählen Sie eine der 3 Karten. Das Band sagt, was es aufwertet.",
  "text.chests_pop_up_on_the_map_every_30_s_the_arrow_at_2bf388": "Truhen tauchen alle 30 s auf der Karte auf (der Pfeil am Bildschirmrand zeigt auf sie).",
